  "book_name": "LAXMANSEN",
  "book_long_title": "কনৌজ বিজয়: বাংলার গৌরবময় অধ্যায় – বল্লাল সেন ও লক্ষ্মণ সেনের অমর কাহিনি",
  "chapter_summary": "একাদশ শতাব্দীর শেষভাগে গৌড়ের সমৃদ্ধির সমান্তরালে পিতা বল্লাল সেনের শাস্ত্রীয় আদর্শ ও পুত্র লক্ষ্মণ সেনের সামরিক উচ্চাকাঙ্ক্ষার মধ্যকার দ্বন্দ্ব এই অধ্যায়ের মূল উপজীব্য। যেখানে বল্লাল সেন সমাজ সংস্কারে মগ্ন, সেখানে লক্ষ্মণ সেন আর্যাবর্ত জয়ের স্বপ্নে বিভোর হয়ে গোপনে এক দুর্ধর্ষ বাহিনী গড়ে তুলছেন।",
  "chapter_segments": [
    {
      "segment_index": 1,
      "name": "setting_the_scene",
      "segment_title": "গৌড়ের অপরাহ্ণ ও রাজকীয় পরিবেশ",
      "segment_seed": "গৌড়ের গঙ্গার তীরে অপরাহ্ণের সূর্য যখন রক্তিম আভা ছড়াচ্ছে, রাজপ্রাসাদের অলিন্দে ধূপের সুগন্ধ আর বেদপাঠে এক শান্তিময় পরিবেশ তৈরি হয়েছে। বাণিজ্যের তরীগুলো বন্দরে ভিড়ছে, যা বাংলার অঢেল ঐশ্বর্যের পরিচয় দেয়।"
    },
    {
      "segment_index": 2,
      "name": "character_debut",
      "segment_title": "মহারাজ বল্লাল সেনের আবির্ভাব",
      "segment_seed": "পণ্ডিতদের মাঝে ধীর স্থিরভাবে উপবিষ্ট মহারাজ বল্লাল সেন। তাঁর হাতে শাস্ত্রীয় পাণ্ডুলিপি ‘দানসাগর’, দৃষ্টিতে সমাজ সংস্কারের স্বপ্ন। তিনি বিশ্বাস করেন তলোয়ারের চেয়ে চরিত্রের পবিত্রতা রাজ্যকে দীর্ঘস্থায়ী করে।"
    },
    {
      "segment_index": 3,
      "name": "status_quo_description",
      "segment_title": "কৌলিন্য প্রথা ও শাস্ত্রীয় শৃঙ্খলা",
